function IncomeGoals({mi,items,currency,loc,t,language,digits,setTab,plan,onUpgrade}:{mi:number;items:Tx[];currency:string;loc:string;t:Record<string,string>;language:Language;digits:NumberSystemCode;setTab:(v:Tab)=>void;plan:"free"|"pro";onUpgrade:()=>void}){const now=new Date();const [goalForm,setGoalForm]=useState(false);const [goalName,setGoalName]=useState("");const [goalTarget,setGoalTarget]=useState("1500000");const [savingTarget,setSavingTarget]=useState(1500000);const [travelTarget,setTravelTarget]=useState(700);const [editingGoalId,setEditingGoalId]=useState("");const [customGoals,setCustomGoals]=useState<{id:string;name:string;target:number}[]>([]);useEffect(()=>{setSavingTarget(Number(localStorage.getItem("novyra-saving-target"))||1500000);const storedTravelTarget=Number(localStorage.getItem("novyra-travel-target"));const safeTravelTarget=storedTravelTarget&&storedTravelTarget!==1500000?storedTravelTarget:700;setTravelTarget(safeTravelTarget);if(safeTravelTarget!==storedTravelTarget)localStorage.setItem("novyra-travel-target",String(safeTravelTarget));try{const raw=localStorage.getItem("novyra-custom-goals");if(raw){const parsed=JSON.parse(raw);if(Array.isArray(parsed))setCustomGoals(parsed)}}catch{}},[]);const savedAmount=items.filter(x=>x.kind==="income"&&["پس‌انداز","Savings"].includes(x.category)).reduce((n,x)=>n+x.amount,0);const pct=Math.min(100,Math.max(0,savedAmount/savingTarget*100));const travelSaved=items.filter(x=>x.kind==="income"&&["پس‌انداز","سرمایه‌گذاری","Travel fund"].includes(x.category)).reduce((n,x)=>n+x.amount,0);const travelPct=Math.min(100,Math.max(0,travelSaved/travelTarget*100));if(language==="en"){const goalCash=(n:number,_currency?:string,_loc?:string,_digits?:NumberSystemCode)=>currency==="IRR"?<bdi dir="ltr">{fmt(n,digits)} ریال</bdi>:currency==="IRT"?<bdi dir="ltr">{fmt(n,digits)} تومان</bdi>:new Intl.NumberFormat(numberSystems.find(item=>item.code===digits)?.locale||loc,{style:"currency",currency,minimumFractionDigits:0,maximumFractionDigits:0}).format(n);const salary=items.filter(x=>x.kind==="income"&&x.category==="Salary").reduce((n,x)=>n+x.amount,0),investments=items.filter(x=>x.kind==="income"&&x.category==="Investments").reduce((n,x)=>n+x.amount,0);const remaining=Math.max(0,savingTarget-savedAmount),travelRemaining=Math.max(0,travelTarget-travelSaved);return <div className="nv-income-page nv-income-en"><section className="nf-panel nv-income-card"><small>My Income · {new Intl.DateTimeFormat("en-US",{month:"short",year:"numeric"}).format(now)}</small><div className="nv-income-amount"><h2>{goalCash(mi,currency,loc,digits)}</h2><button className="nv-income-arrow" onClick={()=>setTab("transactions")} aria-label="View income transactions"><ChevronRight size={17}/></button></div><div className="nv-income-sources"><section><b>{goalCash(salary,currency,loc,digits)}</b><span>Salary</span></section><section><b>{goalCash(investments,currency,loc,digits)}</b><span>Investments</span></section></div></section><div className="nv-goals-head"><h2>Your Goals</h2><button onClick={()=>{setEditingGoalId("");setGoalName("");setGoalTarget("1500000");setGoalForm(v=>!v)}}>Add Goal <b>＋</b></button></div>{goalForm&&<form className="nf-panel nv-goal-create" onSubmit={e=>{e.preventDefault();if(goalName.trim()&&Number(goalTarget)>0){if(plan==="free"&&editingGoalId===""){onUpgrade();return}if(editingGoalId==="saving"){setSavingTarget(Number(goalTarget));localStorage.setItem("novyra-saving-target",goalTarget)}else if(editingGoalId==="travel"){setTravelTarget(Number(goalTarget));localStorage.setItem("novyra-travel-target",goalTarget)}else if(editingGoalId){const next=customGoals.map(g=>g.id===editingGoalId?{...g,name:goalName.trim(),target:Number(goalTarget)}:g);setCustomGoals(next);localStorage.setItem("novyra-custom-goals",JSON.stringify(next))}else{const next=[...customGoals,{id:crypto.randomUUID(),name:goalName.trim(),target:Number(goalTarget)}];setCustomGoals(next);localStorage.setItem("novyra-custom-goals",JSON.stringify(next))}setEditingGoalId("");setGoalName("");setGoalTarget("1500000");setGoalForm(false)}}}><label>Goal name<input required value={goalName} onChange={e=>setGoalName(e.target.value)} placeholder="e.g. New Laptop"/></label><label>Target amount<input required type="number" min="1" value={goalTarget} onChange={e=>setGoalTarget(e.target.value)}/></label><button type="submit">Save Goal</button></form>}<section className="nf-panel nv-goal-card nv-goal-laptop"><div className="nv-goal-topline"><div><b>{goalCash(savedAmount,currency,loc,digits)} to {goalCash(savingTarget,currency,loc,digits)}</b><span>New Laptop</span></div><div className="nv-goal-actions"><span className="nv-goal-remaining">{goalCash(remaining,currency,loc,digits)} to go</span><button className="nv-goal-arrow" onClick={()=>{setEditingGoalId("saving");setGoalName("New Laptop");setGoalTarget(String(savingTarget));setGoalForm(true)}} aria-label="Edit laptop goal"><ArrowRight size={17}/></button></div></div><div className="nv-goal-progress"><div className="nv-goal-track"><i style={{width:pct+"%"}}/></div><span className="nv-goal-percent-badge" style={{left:`clamp(0px, ${pct}%, calc(100% - 40px))`,right:"auto",transform:"none",["--goal-progress" as any]:pct+"%"}}>{pct.toFixed(1)}%</span></div><div className="nv-goal-meta"><span>Jan 1, 2025</span><span>March 31, 2025</span></div><div className="nv-goal-monthly"><span>Monthly Contribution</span><b>{goalCash(250,currency,loc,digits)}</b></div></section><section className="nf-panel nv-goal-card nv-goal-travel"><div className="nv-goal-topline"><div><b>{goalCash(travelSaved,currency,loc,digits)} to {goalCash(travelTarget,currency,loc,digits)}</b><span>Vacation Fund</span></div><div className="nv-goal-actions"><span className="nv-goal-remaining">{goalCash(travelRemaining,currency,loc,digits)} to go</span><button className="nv-goal-arrow" onClick={()=>{setEditingGoalId("travel");setGoalName("Vacation Fund");setGoalTarget(String(travelTarget));setGoalForm(true)}} aria-label="Edit vacation goal"><ArrowRight size={17}/></button></div></div><div className="nv-goal-progress"><div className="nv-goal-track yellow"><i style={{width:travelPct+"%"}}/></div><span className="nv-goal-percent-badge yellow" style={{left:`clamp(0px, ${travelPct}%, calc(100% - 40px))`,right:"auto",transform:"none",["--goal-progress" as any]:travelPct+"%"}}>{travelPct.toFixed(1)}%</span></div><div className="nv-goal-meta"><span>Jan 1, 2025</span><span>Aug 20, 2025</span></div><div className="nv-goal-monthly"><span>Monthly Contribution</span><b>{goalCash(75,currency,loc,digits)}</b></div></section>{customGoals.map(g=><section key={g.id} className="nf-panel nv-goal-card"><div className="nv-goal-topline"><div><b>{goalCash(0,currency,loc,digits)} to {goalCash(g.target,currency,loc,digits)}</b><span>{g.name}</span></div><div className="nv-goal-actions"><span className="nv-goal-remaining">{goalCash(g.target,currency,loc,digits)} to go</span><button className="nv-goal-arrow" onClick={()=>{setEditingGoalId(g.id);setGoalName(g.name);setGoalTarget(String(g.target));setGoalForm(true)}} aria-label="Edit goal"><ArrowRight size={17}/></button></div></div><div className="nv-goal-progress"><div className="nv-goal-track"><i style={{width:"0%"}}/></div><span className="nv-goal-percent-badge" style={{left:"0px",right:"auto",transform:"none",["--goal-progress" as any]:"0%"}}>0%</span></div><div className="nv-goal-meta"><span>Start date</span><span>Target date</span></div><div className="nv-goal-monthly"><span>Monthly Contribution</span><b>{goalCash(0,currency,loc,digits)}</b></div></section>)}</div>} return <div className="nv-income-page"><section className="nf-panel nv-income-card"><small>درآمد من · {new Intl.DateTimeFormat("en-US",{month:"long",year:"numeric"}).format(now)}</small><div className="nv-income-amount"><h2>{cash(mi,currency,loc,digits)}</h2><button className="nv-income-arrow" onClick={()=>setTab("transactions")} aria-label="مشاهده تراکنش‌های درآمد"><ChevronRight size={17}/></button></div><div className="nv-income-sources"><section><span>حقوق</span><b>{cash(items.filter(x=>x.kind==="income"&&["حقوق","Salary"].includes(x.category)).reduce((n,x)=>n+x.amount,0),currency,loc)}</b></section><section><span>سرمایه‌گذاری</span><b>{cash(items.filter(x=>x.kind==="income"&&["سرمایه‌گذاری","Investments"].includes(x.category)).reduce((n,x)=>n+x.amount,0),currency,loc)}</b></section></div></section><div className="nv-goals-head"><h2>اهداف مالی من</h2><button onClick={()=>{setEditingGoalId("");setGoalName("");setGoalTarget("1500000");setGoalForm(v=>!v)}}>+ افزودن هدف</button></div>{goalForm&&<form className="nf-panel nv-goal-create" onSubmit={e=>{e.preventDefault();if(goalName.trim()&&Number(goalTarget)>0){if(plan==="free"&&editingGoalId===""){onUpgrade();return}if(editingGoalId==="saving"){setSavingTarget(Number(goalTarget));localStorage.setItem("novyra-saving-target",goalTarget)}else if(editingGoalId==="travel"){setTravelTarget(Number(goalTarget));localStorage.setItem("novyra-travel-target",goalTarget)}else if(editingGoalId){const next=customGoals.map(g=>g.id===editingGoalId?{...g,name:goalName.trim(),target:Number(goalTarget)}:g);setCustomGoals(next);localStorage.setItem("novyra-custom-goals",JSON.stringify(next))}else{const next=[...customGoals,{id:crypto.randomUUID(),name:goalName.trim(),target:Number(goalTarget)}];setCustomGoals(next);localStorage.setItem("novyra-custom-goals",JSON.stringify(next))}setEditingGoalId("");setGoalName("");setGoalTarget("1500000");setGoalForm(false)}}}><label>نام هدف<input required value={goalName} onChange={e=>setGoalName(e.target.value)} placeholder="مثلاً خرید لپ‌تاپ"/></label><label>مبلغ هدف<input required type="number" min="1" value={goalTarget} onChange={e=>setGoalTarget(e.target.value)}/></label><button type="submit">ثبت هدف</button></form>}<section className="nf-panel nv-goal-card"><div className="nv-goal-title"><b>هدف پس‌انداز</b><button className="nv-goal-arrow" onClick={()=>{setEditingGoalId("saving");setGoalName("هدف پس‌انداز");setGoalTarget(String(savingTarget));setGoalForm(true)}} aria-label="ویرایش هدف"><ChevronRight size={17}/></button></div><p className="nv-goal-amount-row">{cash(savedAmount,currency,loc,digits)} از {cash(savingTarget,currency,loc,digits)}</p><div className="nv-goal-track"><i style={{width:pct+"%"}}/><span className="nv-goal-percent-badge" style={{right:"12px",transform:"translateY(-50%)"}}>{fmt(Math.round(pct),digits)}%</span></div><div className="nv-goal-meta"><span>شروع: {new Intl.DateTimeFormat("en-US",{year:"numeric",month:"short",day:"numeric"}).format(now)}</span><span>پایان: {new Intl.DateTimeFormat("en-US",{year:"numeric",month:"short",day:"numeric"}).format(new Date(now.getFullYear(),now.getMonth()+4,now.getDate()))}</span></div><small className="nv-goal-monthly">مشارکت ماهانه · {cash(500000,currency,loc,digits)}</small></section><section className="nf-panel nv-goal-card nv-goal-travel"><div className="nv-goal-title"><b>صندوق سفر</b><button className="nv-goal-arrow" onClick={()=>{setEditingGoalId("travel");setGoalName("صندوق سفر");setGoalTarget(String(travelTarget));setGoalForm(true)}} aria-label="ویرایش صندوق سفر"><ChevronRight size={17}/></button></div><p className="nv-goal-amount-row">{cash(travelSaved,currency,loc,digits)} از {cash(travelTarget,currency,loc,digits)}</p><div className="nv-goal-track yellow"><i style={{width:travelPct+"%"}}/><span className="nv-goal-percent-badge yellow" style={{right:"12px",transform:"translateY(-50%)"}}>{fmt(Math.round(travelPct),digits)}%</span></div><div className="nv-goal-meta"><span>شروع: {new Intl.DateTimeFormat("en-US",{year:"numeric",month:"short",day:"numeric"}).format(now)}</span><span>پایان: {new Intl.DateTimeFormat("en-US",{year:"numeric",month:"short",day:"numeric"}).format(new Date(now.getFullYear()+1,now.getMonth()+2,now.getDate()))}</span></div><small className="nv-goal-monthly">مشارکت ماهانه · {cash(250000,currency,loc,digits)}</small></section>{customGoals.map(g=><section key={g.id} className="nf-panel nv-goal-card"><div className="nv-goal-title"><b>{g.name}</b><button className="nv-goal-arrow" onClick={()=>{setEditingGoalId(g.id);setGoalName(g.name);setGoalTarget(String(g.target));setGoalForm(true)}} aria-label="ویرایش هدف"><ChevronRight size={17}/></button></div><p className="nv-goal-amount-row">{cash(0,currency,loc,digits)} از {cash(g.target,currency,loc,digits)}</p><div className="nv-goal-track"><i style={{width:"0%"}}/><span className="nv-goal-percent-badge">0%</span></div></section>)}</div>}

function SettingsPanel({account,plan,monthlyCount,referralCode,onUpgrade,prefs,setPrefs,currency,setCurrency,language,onLanguageChange,theme,setTheme,items,setItems,onExport,onLogout,onMessage,setShowBalance,accountType="personal",onAccountTypeChange,appLockType="none",onAppLockChange}:{account:Account;plan:"free"|"pro";monthlyCount:number;referralCode:string;onUpgrade:()=>void;prefs:Preferences;setPrefs:(v:Preferences)=>void;currency:string;setCurrency:(v:string)=>void;language:Language;onLanguageChange:(v:Language)=>void;theme:"light"|"dark"|"auto";setTheme:(v:"light"|"dark"|"auto")=>void;items:Tx[];setItems:(v:Tx[]|((p:Tx[])=>Tx[]))=>void;onExport:()=>void;onLogout:()=>void;onMessage:(v:string)=>void;setShowBalance:(v:boolean)=>void;accountType?:"personal"|"business";onAccountTypeChange?:(v:"personal"|"business")=>void;appLockType?:"none"|"pin"|"pattern"|"biometric";onAppLockChange?:(type:"none"|"pin"|"pattern",secret:string)=>Promise<void>}){
 const en=language==="en";const categoryLabel=(c:string)=>en?({"عمومی":"General","خوراک":"Food","حمل‌ونقل":"Transport","خانه":"Housing","سلامت":"Health","آموزش":"Education","حقوق":"Salary","سرمایه‌گذاری":"Investments","پس‌انداز":"Savings","فروش":"Sales","قبض":"Bills","سایر":"Other"} as Record<string,string>)[c]||c:c; const [newCategory,setNewCategory]=useState("");const [newBudgetCategory,setNewBudgetCategory]=useState("خوراک");const [lockChoice,setLockChoice]=useState<"none"|"pin"|"pattern">(appLockType==="biometric"?"none":appLockType);const [lockSecret,setLockSecret]=useState("");const [lockBusy,setLockBusy]=useState(false);
 const update=(patch:Partial<Preferences>)=>setPrefs({...prefs,...patch});
 const updateReminder=(key:keyof Preferences["reminders"],value:boolean)=>update({reminders:{...prefs.reminders,[key]:value}});
 const backup=()=>{const payload={format:"novyra-backup-v1",createdAt:new Date().toISOString(),transactions:items,preferences:prefs,goals:JSON.parse(localStorage.getItem("novyra-custom-goals")||"[]"),savingTarget:localStorage.getItem("novyra-saving-target"),travelTarget:localStorage.getItem("novyra-travel-target")};const url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:"application/json"}));const a=document.createElement("a");a.href=url;a.download="novyra-backup.json";a.click();URL.revokeObjectURL(url)};
 const restore=async(file?:File)=>{if(!file)return;try{const data=JSON.parse(await file.text());if(data.format!=="novyra-backup-v1"||!Array.isArray(data.transactions))throw new Error("فرمت فایل پشتیبان معتبر نیست.");setItems(data.transactions);if(data.preferences)setPrefs({...defaultPreferences,...data.preferences});if(Array.isArray(data.goals))localStorage.setItem("novyra-custom-goals",JSON.stringify(data.goals));if(data.savingTarget)localStorage.setItem("novyra-saving-target",data.savingTarget);if(data.travelTarget)localStorage.setItem("novyra-travel-target",data.travelTarget);onMessage("پشتیبان با موفقیت بازیابی شد.")}catch(e){onMessage(e instanceof Error?e.message:"بازیابی فایل ناموفق بود.")}};
 const clearData=()=>{if(!window.confirm("تمام تراکنش‌ها و اهداف ذخیره‌شده روی این دستگاه پاک شوند؟"))return;if(!window.confirm("این کار برگشت‌پذیر نیست. برای تأیید نهایی، دوباره تأیید کن."))return;setItems([]);localStorage.removeItem("novyra-custom-goals");localStorage.removeItem("novyra-saving-target");localStorage.removeItem("novyra-travel-target");onMessage("داده‌های مالی این دستگاه پاک شدند.")};
 const addCategory=()=>{const value=newCategory.trim();if(!value||prefs.categories.includes(value))return;update({categories:[...prefs.categories,value]});setNewCategory("")};
 const removeCategory=(value:string)=>{if(!window.confirm("دسته «"+value+"» حذف شود؟ تراکنش‌های قبلی آن باقی می‌مانند."))return;update({categories:prefs.categories.filter(x=>x!==value)});if(newBudgetCategory===value)setNewBudgetCategory(prefs.categories.find(x=>x!==value)||"عمومی")};
 const setCategoryBudget=(name:string,value:string)=>update({categoryBudgets:{...prefs.categoryBudgets,[name]:value}});
 return <div className="nf-settings">
 <section className="nf-setting-section"><h3>{en?("Account & "+"Pro\u0066ile"):"حساب و پروفایل"}</h3><label>{en?"Display name":"نام نمایشی"}<input value={prefs.profileName||account.displayName} onChange={e=>update({profileName:e.target.value})} onBlur={()=>localStorage.setItem("novyra-profile-name",prefs.profileName||account.displayName)}/><small>{en?"This name is stored on this device only; account-wide editing is Not available in this build.":"این نام فعلاً فقط روی همین دستگاه ذخیره می‌شود؛ تغییر نام حساب اصلی · در این نسخه فعال نیست"}</small></label><label>{en?"Account email":"ایمیل حساب"}<input value={account.email.replace(/^(.{2}).*(@.*)$/,"$1••••$2")} readOnly/><small>{en?"Email change and verification · Not available in this build":"تغییر و تأیید ایمیل · در این نسخه فعال نیست"}</small></label><div className="nf-setting-actions"><button type="button" className="nf-quiet" onClick={()=>onMessage("تغییر رمز حساب در این نسخه فعال نیست فعال می‌شود.")}>{en?"Change password · Not available in this build":"تغییر رمز · در این نسخه فعال نیست"}</button><button type="button" className="nf-danger" onClick={()=>onMessage("حذف امن حساب · در این نسخه فعال نیست")}>{en?"Delete account":"حذف حساب"}</button></div></section>
 <section className="nf-setting-section"><h3>{en?"Subscription":"اشتراک"}</h3><div className="nf-plan-card"><div><small>{en?"Current plan":"پلن فعلی"}</small><b>{en?"Free":"رایگان"}</b><span>{en?"No expiration date":"بدون تاریخ انقضا"}</span></div><strong>{en?"Free":"رایگان"}</strong></div><p>{en?"Pro includes advanced reports, unlimited exports, cloud backup and unlimited goals.":"پلن پرو: گزارش‌های پیشرفته، خروجی نامحدود، پشتیبان‌گیری ابری و اهداف نامحدود."}</p><div className="nf-setting-note">{plan==="pro"?(en?"Pro is active on this device":"پلن پرو فعال روی همین دستگاه"):(en?`This month: ${monthlyCount} of 50 transactions`:`مصرف این ماه: ${monthlyCount} از 50 تراکنش`)}</div><div className="nf-setting-actions"><button type="button" className="nf-primary" onClick={onUpgrade}>{en?"Explore Pro plans":"مشاهده پلن‌های پرو"}</button></div><div className="nf-setting-note">{en?"Payment history: no payments yet. Renewal reminders can be enabled after subscription and notification services are connected.":"تاریخچه پرداخت: هنوز پرداختی ثبت نشده است. یادآوری‌های 7 و 1 روز قبل از پایان، پس از اتصال سرویس اشتراک و اعلان‌ها قابل فعال‌سازی هستند."}</div></section>
 <section className="nf-setting-section"><h3>{en?"Invite friends":"دعوت دوستان"}</h3><p>{en?"Your referral code:":"کد معرفی شما:"} <bdi>{referralCode}</bdi></p><button type="button" className="nf-quiet" onClick={()=>{const link=location.origin+"/?ref="+referralCode;if(navigator.share)navigator.share({title:"NOVYRA",text:en?"Invite a friend — you can both receive 7 days of Pro":"با هر دوستی که بیاید، هر دو 7 روز پرو می‌گیرید",url:link}).catch(()=>{});else navigator.clipboard?.writeText(link);}}>{en?"Share invite link":"اشتراک‌گذاری لینک دعوت"}</button><small>{en?"You and a friend can each receive 7 days of Pro after the referral service is connected.":"با هر دوستی که بیاید، هر دو 7 روز پرو می‌گیرید. فعال‌سازی پاداش پس از اتصال سرویس معرفی انجام می‌شود."}</small></section><section className="nf-setting-section"><h3>{en?"Notifications":"اعلان‌ها"}</h3>{([["daily",en?"Daily entry reminder":"یادآوری ثبت روزانه"],["limit",en?"Budget limit warning":"هشدار نزدیک‌شدن به سقف هزینه"],["renewal",en?"Subscription renewal reminder":"یادآوری تمدید اشتراک"]] as [keyof Preferences["reminders"],string][]).map(([key,label])=><label className="nf-switch-row" key={key}>{label}<input type="checkbox" checked={prefs.reminders[key]} onChange={e=>updateReminder(key,e.target.checked)}/></label>)}<small>{en?"Preferences are saved; background and push notifications still require a notification service.":"انتخاب‌ها ذخیره می‌شوند؛ اعلان پس‌زمینه و Push هنوز به سرویس اعلان نیاز دارد."}</small></section>
 <section className="nf-setting-section"><h3>{en?"Budget":"بودجه"}</h3><label>{en?"Monthly spending limit":"سقف هزینه ماهانه"} ({currency})<input inputMode="numeric" value={prefs.monthlyBudget?Number(prefs.monthlyBudget).toLocaleString("en-US"):""} onChange={e=>update({monthlyBudget:e.target.value.replace(/[^0-9]/g,"")})} placeholder={en?"e.g. 10000000":"مثلاً 10000000"}/></label><label>{en?"Category budget":"دسته‌بندی برای تعیین سقف"}<select value={newBudgetCategory} onChange={e=>setNewBudgetCategory(e.target.value)}>{prefs.categories.map(c=><option key={c}>{c}</option>)}</select></label><label>{en?"Category limit":"سقف دسته"} ({currency})<input inputMode="numeric" value={prefs.categoryBudgets[newBudgetCategory]?Number(prefs.categoryBudgets[newBudgetCategory]).toLocaleString("en-US"):""} onChange={e=>setCategoryBudget(newBudgetCategory,e.target.value.replace(/[^0-9]/g,""))} placeholder={en?"No limit":"بدون سقف"}/></label><small>{en?"Spending cards are calculated from your saved limits.":"وضعیت کارت‌های هزینه بر اساس سقف ثبت‌شده محاسبه می‌شود."}</small></section>
 <section className="nf-setting-section"><h3>{en?"Categories":"دسته‌بندی‌ها"}</h3><div className="nf-category-add"><input value={newCategory} onChange={e=>setNewCategory(e.target.value)} placeholder={en?"New category name":"نام دسته جدید"}/><button type="button" onClick={addCategory}>{en?"Add":"افزودن"}</button></div><div className="nf-category-list">{[...new Set(prefs.categories)].map(c=><div key={c}><span>{categoryLabel(c)}</span><button type="button" onClick={()=>removeCategory(c)} aria-label={(en?"Remove ":"حذف ")+c}>×</button></div>)}</div><small>{en?"Removing a category does not delete past transactions.":"حذف دسته، تراکنش‌های قبلی را پاک نمی‌کند."}</small></section>
 <section className="nf-setting-section"><h3>{en?"Data & Backup":"داده‌ها و پشتیبان‌گیری"}</h3><div className="nf-setting-actions"><button type="button" className="nf-quiet" onClick={onExport}>{en?"Export CSV":"خروجی CSV"} {plan==="free"?"🔒":""}</button><button type="button" className="nf-quiet" onClick={()=>plan==="pro"?backup():onUpgrade()}>{en?"Download JSON backup":"دانلود پشتیبان JSON"} {plan==="free"?"🔒":""}</button></div><label className="nf-file-label">{en?"Restore backup":"بازیابی پشتیبان"}<input type="file" accept="application/json,.json" onChange={e=>{if(plan==="pro")restore(e.target.files?.[0]);else onUpgrade()}}/></label><div className="nf-setting-actions"><button type="button" className="nf-danger" onClick={clearData}>{en?"Delete all data":"پاک‌کردن همه داده‌ها"}</button></div><div className="nf-setting-note">{en?"Cloud sync · Not available in this build; data is currently stored in this browser only.":"همگام‌سازی ابری · در این نسخه فعال نیست؛ فعلاً داده‌ها فقط روی همین مرورگر ذخیره می‌شوند."}</div></section>
 <section className="nf-setting-section"><h3>{en?"Appearance":"ظاهر و قالب"}</h3><label>{en?"Theme":"پوسته"}<select value={theme} onChange={e=>{setTheme(e.target.value as "light"|"dark"|"auto");update({theme:e.target.value as Preferences["theme"]})}}><option value="light">{en?"Light":"روشن"}</option><option value="dark">{en?"Dark":"تاریک"}</option><option value="auto">{en?"System":"خودکار"}</option></select></label><label>{en?"Country":"کشور"}<select value={prefs.country} onChange={e=>{const selected=countries.find(item=>item.code===e.target.value);if(selected){const nextDate=selected.code==="IR"?"YYYY/MM/DD":new Intl.DateTimeFormat(selected.defaultLanguage||"en",{year:"numeric",month:"2-digit",day:"2-digit"}).formatToParts(new Date(2025,10,24)).map(part=>part.type==="year"?"YYYY":part.type==="month"?"MM":part.type==="day"?"DD":part.value).join("");localStorage.setItem("projectx-country",selected.code);localStorage.setItem("novyra-date-format",nextDate);update({country:e.target.value,calendar:selected.defaultCalendar as CalendarCode,firstDay:selected.weekStart,digits:selected.defaultNumberSystem,dateFormat:nextDate});if(selected.defaultCurrency)setCurrency(selected.defaultCurrency);onLanguageChange(selected.defaultLanguage as Language);}}}>{countries.map(item=><option key={item.code} value={item.code}>{item.flag} {en?item.name:item.nativeName} · {item.code}</option>)}</select></label><label>{en?"Calendar":"تقویم"}<select value={prefs.calendar} onChange={e=>update({calendar:e.target.value as CalendarCode})}>{calendars.map(item=><option key={item.code} value={item.code}>{en?item.name:item.nativeName}</option>)}</select></label><label>{en?"Date format":"قالب تاریخ"}<select value={prefs.dateFormat} onChange={e=>update({dateFormat:e.target.value})}>{["DD/MM/YYYY","MM/DD/YYYY","YYYY-MM-DD","YYYY/MM/DD"].map(item=><option key={item}>{item}</option>)}</select></label><label>{en?"Number system":"نمایش ارقام"}<select value={prefs.digits} onChange={e=>update({digits:e.target.value as NumberSystemCode})}>{numberSystems.map(item=><option key={item.code} value={item.code}>{en?item.name:item.nativeName}</option>)}</select></label><label>{en?"First day of week":"اولین روز هفته"}<select value={prefs.firstDay} onChange={e=>update({firstDay:e.target.value as WeekStartCode})}>{weekdays.map(item=><option key={item.code} value={item.code}>{en?item.name:item.nativeName}</option>)}</select></label><label>{en?"Language":"زبان"}<select value={language} onChange={e=>onLanguageChange(e.target.value as Language)}>{languages.map(item=><option key={item.code} value={item.code}>{item.nativeName} · {item.name}</option>)}</select></label>{!hasTranslation&&<div className="nf-setting-note" role="status">Translation not available yet — English fallback is active.</div>}<label>{en?"Currency":"واحد پول"}<select value={currency} onChange={e=>setCurrency(e.target.value)}>{currencies.map(item=><option key={item.code} value={item.code}>{item.code} — {en?item.name:item.symbol+" "+item.name}</option>)}</select></label></section>
 <section className="nf-setting-section"><h3>{en?"Security & Privacy":"امنیت و حریم خصوصی"}</h3><label className="nf-switch-row">{en?"Hide amounts by default":"مخفی‌کردن مبلغ‌ها به‌صورت پیش‌فرض"}<input type="checkbox" checked={prefs.hideAmounts} onChange={e=>{update({hideAmounts:e.target.checked});setShowBalance(!e.target.checked);localStorage.setItem("novyra-hide-amounts",String(e.target.checked))}}/></label><label>{en?"App lock":"قفل برنامه"}<select value={lockChoice} onChange={e=>setLockChoice(e.target.value as "none"|"pin"|"pattern")}><option value="none">{en?"Off":"خاموش"}</option><option value="pin">PIN</option><option value="pattern">{en?"Pattern":"الگو"}</option></select></label>{lockChoice!=="none"&&<label>{en?"New PIN or pattern":"رمز یا الگوی جدید"}<input type="password" autoComplete="off" value={lockSecret} onChange={e=>setLockSecret(e.target.value)} minLength={4}/></label>}<button type="button" disabled={lockBusy||!onAppLockChange||(lockChoice==="pin"&&lockSecret.length<6||lockChoice==="pattern"&&lockSecret.length<4)} onClick={async()=>{setLockBusy(true);try{await onAppLockChange?.(lockChoice,lockSecret);setLockSecret("");onMessage(en?"App lock settings saved.":"تنظیمات قفل برنامه ذخیره شد.");}catch(error){onMessage(error instanceof Error?error.message:"Could not save app lock.");}finally{setLockBusy(false);}}}>{lockBusy?"…":(en?"Save app lock":"ذخیره قفل برنامه")}</button></section><section className="nf-setting-section"><h3>{en?"Account type":"نوع حساب"}</h3><select value={accountType} onChange={e=>onAccountTypeChange?.(e.target.value as "personal"|"business")}><option value="personal">{en?"Personal":"شخصی"}</option><option value="business">{en?"Business":"تجاری"}</option></select></section>
 <section className="nf-setting-section"><h3>{en?"Support & Legal":"پشتیبانی و حقوقی"}</h3><p>{en?"Support, FAQs, terms and privacy information will be published here when the official pages are ready.":"پشتیبانی، سؤالات متداول، شرایط استفاده و حریم خصوصی باید با نشانی رسمی و محتوای تأییدشده منتشر شوند."}</p><div className="nf-setting-note">{en?"App version: NOVYRA":"نسخه برنامه: NOVYRA"}</div></section>
 <section className="nf-setting-section nf-logout-card"><h3>{en?"Sign out":"خروج از حساب"}</h3><button className="nf-logout" onClick={()=>{if(window.confirm(en?"Are you sure you want to sign out?":"برای خروج از حساب مطمئنی؟"))onLogout()}}><LogOut size={15}/>{en?"Sign out":"خروج از حساب"}</button></section>
 </div>
}

function Paywall({onClose,onStart}:{onClose:()=>void;onStart:()=>void}){return <div className="nf-modal-backdrop" onClick={e=>{if(e.target===e.currentTarget)onClose()}}><section className="nf-modal nf-paywall" dir="rtl"><div className="nf-modal-head"><h2>ارتقا به NOVYRA پرو</h2><button onClick={onClose}><X size={18}/></button></div><p>تراکنش نامحدود، اهداف بیشتر، گزارش چاپی و امکانات پیشرفته.</p><div className="nf-plan-options"><article><b>ماهانه</b><strong>قیمت پس از اتصال درگاه</strong></article><article><b>سه‌ماهه</b><strong>قیمت پس از اتصال درگاه</strong></article><article><b>سالانه</b><em>صرفه‌جویی 35%</em><strong>قیمت پس از اتصال درگاه</strong></article></div><div className="nf-trial-note">7 روز آزمایشی محلی؛ وضعیت پرداخت واقعی فعال نیست.</div><button className="nf-primary nf-pay-start" onClick={onStart}>شروع</button><small>پرداخت پس از اتصال درگاه فعال می‌شود.</small></section></div>}
function TxRow({x,currency,locale,digits,del,t}:{x:Tx;currency:string;locale:string;digits:NumberSystemCode;del:(id:string)=>void;t:Record<string,string>}){return <article className="nf-transaction"><span className={"nf-tx-icon "+x.kind}>{x.kind==="income"?<ArrowDownLeft size={16}/>:<ArrowUpRight size={16}/>}</span><div className="nf-tx-title"><b>{x.title}</b><small>{x.category} · {(prefs.dateFormat||"YYYY/MM/DD").replace("YYYY",x.date.slice(0,4)).replace("MM",x.date.slice(5,7)).replace("DD",x.date.slice(8,10))}</small></div><strong className={x.kind==="income"?"positive":"negative"}>{x.kind==="income"?"+":"−"}{cash(x.amount,currency,locale,digits)}</strong><button onClick={()=>del(x.id)} title={t.delete}><X size={14}/></button></article>}
function Empty({title,sub,add,label}:{title:string;sub:string;add?:()=>void;label?:string}){return <div className="nf-empty"><span>◇</span><h3>{title}</h3><p>{sub}</p>{add&&<button onClick={add}>{label}</button>}</div>}
